const self = stats.find(s => s.id === currentStatId);
if (self.value <= 0) return 0;
if (self.value >= self.max) return 0; // full term -> birth
return self.value + 1;

const self = stats.find(s => s.id === currentStatId);
const preg = stats.find(s => s.name === 'Pregnancy');
const t = preg ? preg.value / preg.max : 0;
return Math.round(t * self.max);

const self = stats.find(s => s.id === currentStatId);
const preg = stats.find(s => s.name === 'Pregnancy');
if (preg && preg.value > 0) return 0;
return self.value < 25 ? Math.min(25, self.value + 5) : self.value;
